import { IMAGE_SIZES } from '../data/imageSizes'

// Drop-in <img> that stamps on the intrinsic width/height generated by
// scripts/optimize-images.mjs, so the browser reserves the right space before
// the file arrives. Without this the page reflows as images load, which breaks
// anchor scrolling and shifts content under the reader.
export default function Img({ src, ...props }) {
  const size = IMAGE_SIZES[src]
  return <img src={src} width={size?.width} height={size?.height} {...props} />
}
